import { randomId } from "../core/blueprint/ids";
import { asString } from "../core/registry/data";
import { MODULE_SCOPE } from "../core/storage/repository";
import { OPERATION_KINDS, type Operation } from "../runtime/operations";
import { listOf, read } from "../runtime/read";
import { canRunLocally, executeOperation } from "./operations";

const CHANNEL = `module.${MODULE_SCOPE}`;
const TIMEOUT_MS = 15_000;

interface Reply {
  ok: boolean;
  error: string | null;
}

const waiting = new Map<string, (reply: Reply) => void>();

function isOperation(value: unknown): value is Operation {
  return OPERATION_KINDS.includes(asString(read(value, "kind")) as Operation["kind"]) && (typeof read(value, "actor") === "string");
}

async function onMessage(message: unknown): Promise<void> {
  const type = read(message, "type");
  const id = asString(read(message, "id"));
  if (type === "reply") {
    if (read(message, "recipient") !== game.user.id) return;
    waiting.get(id)?.({ ok: read(message, "ok") === true, error: asString(read(message, "error")) || null });
    return;
  }
  if ((type !== "operations") || !game.user.isGM || (read(message, "gm") !== game.user.id)) return;
  let error: string | null = null;
  for (const op of listOf(read(message, "operations")).filter(isOperation)) {
    try {
      await executeOperation(op);
    } catch (failure) {
      error = (failure instanceof Error) ? failure.message : String(failure);
      console.warn("Build-n-Action | a requested change failed", op, failure);
    }
  }
  game.socket.emit(CHANNEL, { type: "reply", id, recipient: read(message, "sender"), ok: error === null, error });
}

export function registerSocket(): void {
  game.socket.on(CHANNEL, message => {
    void onMessage(message);
  });
}

/** Make changes: locally where allowed, through the active GM otherwise. False when something was skipped. */
export async function performOperations(operations: readonly Operation[]): Promise<boolean> {
  const remote: Operation[] = [];
  let ok = true;
  for (const op of operations) {
    if (!canRunLocally(op)) {
      remote.push(op);
      continue;
    }
    try {
      await executeOperation(op);
    } catch (error) {
      ok = false;
      console.warn("Build-n-Action | a change failed", op, error);
    }
  }
  if (!remote.length) return ok;

  const gm = game.users.activeGM;
  if (!gm) {
    ui.notifications.warn(game.i18n.localize("BNA.Runtime.NoGM"));
    return false;
  }
  const id = randomId();
  const reply = new Promise<Reply | null>(resolve => {
    const timer = setTimeout(() => {
      waiting.delete(id);
      resolve(null);
    }, TIMEOUT_MS);
    waiting.set(id, answer => {
      clearTimeout(timer);
      waiting.delete(id);
      resolve(answer);
    });
  });
  game.socket.emit(CHANNEL, { type: "operations", id, sender: game.user.id, gm: gm.id, operations: remote });
  const answer = await reply;
  if (!answer?.ok) {
    console.warn("Build-n-Action | the GM could not make all changes", answer?.error ?? "no reply");
    ui.notifications.warn(game.i18n.localize("BNA.Runtime.RemoteFailed"));
    return false;
  }
  return ok;
}
